datasource db {
  provider = "sqlite"
  // Wasp requires that the url is set to the DATABASE_URL environment variable.
  url      = env("DATABASE_URL")
}

// Wasp requires the `prisma-client-js` generator to be present.
generator client {
  provider = "prisma-client-js"
}

model User {
  id        Int       @id @default(autoincrement())
  username  String    @unique
  createdAt DateTime  @default(now())
  comments  Comment[]
  posts     Post[]
}

model Post {
  id        Int       @id @default(autoincrement())
  title     String
  createdAt DateTime  @default(now())
  authorId  Int?
  author    User?     @relation(fields: [authorId], references: [id])
  comments  Comment[]
}

model Comment {
  id            Int       @id @default(autoincrement())
  content       String
  createdAt     DateTime  @default(now())
  postId        Int
  post          Post      @relation(fields: [postId], references: [id], onDelete: Cascade)
  authorId      Int
  author        User      @relation(fields: [authorId], references: [id])
  // Self-referential relation: each comment may be a reply to another comment.
  parentId      Int?
  parent        Comment?  @relation("CommentReplies", fields: [parentId], references: [id], onDelete: Cascade)
  children      Comment[] @relation("CommentReplies")

  @@index([postId])
  @@index([parentId])
}

app nestedComments {
  wasp: {
    version: "^0.16.8"
  },
  title: "nested-comments",
  db: {
    seeds: [
      import { devSeed } from "@src/server/seeds.js"
    ]
  }
}

route RootRoute { path: "/", to: MainPage }
page MainPage {
  component: import { MainPage } from "@src/MainPage.jsx"
}

route PostRoute { path: "/post/:postId", to: PostPage }
page PostPage {
  component: import { PostPage } from "@src/PostPage.jsx"
}

query getPosts {
  fn: import { getPosts } from "@src/server/queries.js",
  entities: [Post]
}

query getCommentTree {
  fn: import { getCommentTree } from "@src/server/queries.js",
  entities: [Comment, Post, User]
}

action createComment {
  fn: import { createComment } from "@src/server/actions.js",
  entities: [Comment, Post, User]
}

action deleteComment {
  fn: import { deleteComment } from "@src/server/actions.js",
  entities: [Comment]
}

/**
 * Queries callable from the client (and server) of the Wasp app.
 * Each named export corresponds to a `query` declaration in `main.wasp`.
 */

/**
 * getPosts: returns every post in the database. Each element has the
 * keys `id` (number) and `title` (string), plus a few more for
 * convenience (createdAt, authorUsername).
 */
export const getPosts = async (_args, context) => {
  if (!context.entities || !context.entities.Post) {
    throw new Error("Post entity is not available on the query context.");
  }
  const posts = await context.entities.Post.findMany({
    orderBy: { id: "asc" },
    include: {
      author: {
        select: { username: true },
      },
    },
  });
  return posts.map((p) => ({
    id: p.id,
    title: p.title,
    createdAt: p.createdAt,
    authorUsername: p.author ? p.author.username : null,
  }));
};

/**
 * getCommentTree: given a post, returns the post's top-level comments
 * (those with no parent), with each node containing the keys:
 *   { id, content, authorUsername, parentId, children }
 * where `children` is an array of the same shape, recursively nested
 * to any depth. Sibling nodes are ordered by ascending `id` at every
 * level.
 */
export const getCommentTree = async (args, context) => {
  const postId = args && args.postId;
  if (postId === undefined || postId === null) {
    throw new Error("getCommentTree requires a postId argument.");
  }

  // Make sure the post exists (helps give a clear error if it doesn't).
  const post = await context.entities.Post.findUnique({
    where: { id: postId },
  });
  if (!post) {
    return [];
  }

  // Fetch every comment for the post in a single query, including the
  // author so we can produce `authorUsername`.
  const flatComments = await context.entities.Comment.findMany({
    where: { postId: postId },
    orderBy: { id: "asc" },
    include: {
      author: {
        select: { username: true },
      },
    },
  });

  // Index by id for O(n) tree assembly.
  const byId = new Map();
  for (const c of flatComments) {
    byId.set(c.id, {
      id: c.id,
      content: c.content,
      authorUsername: c.author ? c.author.username : null,
      parentId: c.parentId,
      children: [],
    });
  }

  // Assemble the tree, then collect the top-level nodes.
  const roots = [];
  for (const node of byId.values()) {
    if (node.parentId == null) {
      roots.push(node);
    } else {
      const parent = byId.get(node.parentId);
      if (parent) {
        parent.children.push(node);
      } else {
        // Orphaned comment (parent got deleted). Treat as a root so
        // it remains visible to the user.
        roots.push(node);
      }
    }
  }

  return roots;
};

/**
 * Actions callable from the client (and server) of the Wasp app.
 * Each named export corresponds to an `action` declaration in `main.wasp`.
 */

/**
 * createComment: creates a comment on a post, authored by the user
 * with the given `authorUsername`. If `parentId` is provided (and not
 * null), the new comment is a reply to that existing comment;
 * otherwise it is a top-level comment on the post.
 *
 * Returns the created comment object, including its `id`.
 */
export const createComment = async (args, context) => {
  const { postId, authorUsername, content, parentId } = args || {};

  if (postId === undefined || postId === null) {
    throw new Error("createComment requires a `postId`.");
  }
  if (!authorUsername || typeof authorUsername !== "string") {
    throw new Error("createComment requires an `authorUsername` string.");
  }
  if (!content || typeof content !== "string") {
    throw new Error("createComment requires a `content` string.");
  }

  // Verify the post exists.
  const post = await context.entities.Post.findUnique({
    where: { id: postId },
  });
  if (!post) {
    throw new Error(`Post with id ${postId} not found.`);
  }

  // Look up the author by username.
  const author = await context.entities.User.findUnique({
    where: { username: authorUsername },
  });
  if (!author) {
    throw new Error(`User with username '${authorUsername}' not found.`);
  }

  // If a parentId was supplied, verify the parent comment exists and
  // belongs to the same post.
  let resolvedParentId = null;
  if (parentId !== undefined && parentId !== null) {
    const parent = await context.entities.Comment.findUnique({
      where: { id: parentId },
    });
    if (!parent) {
      throw new Error(`Parent comment with id ${parentId} not found.`);
    }
    if (parent.postId !== postId) {
      throw new Error(
        `Parent comment ${parentId} does not belong to post ${postId}.`
      );
    }
    resolvedParentId = parent.id;
  }

  const created = await context.entities.Comment.create({
    data: {
      content,
      postId: postId,
      authorId: author.id,
      parentId: resolvedParentId,
    },
    include: {
      author: {
        select: { username: true },
      },
    },
  });

  return {
    id: created.id,
    content: created.content,
    postId: created.postId,
    authorId: created.authorId,
    authorUsername: created.author ? created.author.username : null,
    parentId: created.parentId,
    createdAt: created.createdAt,
  };
};

/**
 * deleteComment: deletes a comment AND all of its descendant replies
 * (the entire subtree beneath it). We rely on Prisma's
 * `onDelete: Cascade` on the Comment self-relation, so deleting the
 * root of the subtree cascades to every descendant.
 */
export const deleteComment = async (args, context) => {
  const { commentId } = args || {};
  if (commentId === undefined || commentId === null) {
    throw new Error("deleteComment requires a `commentId`.");
  }

  const existing = await context.entities.Comment.findUnique({
    where: { id: commentId },
  });
  if (!existing) {
    // Idempotent: deleting a non-existent comment is a no-op.
    return { ok: true, deletedCount: 0 };
  }

  // Collect the entire subtree (the comment itself plus all
  // descendants) so we can report a count and so the cascade is
  // observable even if the cascade is disabled.
  const subtreeIds = await collectSubtreeIds(context.entities.Comment, commentId);

  await context.entities.Comment.delete({
    where: { id: commentId },
  });

  return { ok: true, deletedCount: subtreeIds.length };
};

/**
 * Returns the ids of the comment subtree rooted at `rootId`,
 * including `rootId` itself. Performs a BFS using Prisma queries.
 */
async function collectSubtreeIds(commentDelegate, rootId) {
  const ids = [];
  const queue = [rootId];
  while (queue.length > 0) {
    const current = queue.shift();
    ids.push(current);
    const children = await commentDelegate.findMany({
      where: { parentId: current },
      select: { id: true },
    });
    for (const child of children) {
      queue.push(child.id);
    }
  }
  return ids;
}

/**
 * Idempotent dev seed: creates two users (`alice` and `bob`) and a
 * single post titled `Wasp Nested Comments`. Running the seed more
 * than once MUST NOT create duplicates — we use `upsert` for each
 * record.
 *
 * Run with: `wasp db seed devSeed`
 */
export const devSeed = async (prismaClient) => {
  // Create (or keep) the two users.
  const alice = await prismaClient.user.upsert({
    where: { username: "alice" },
    update: {},
    create: {
      username: "alice",
    },
  });

  const bob = await prismaClient.user.upsert({
    where: { username: "bob" },
    update: {},
    create: {
      username: "bob",
    },
  });

  // Create (or keep) the post titled "Wasp Nested Comments".
  // We look up an existing post by title and only create it if it's
  // missing — this keeps the seed idempotent without requiring a
  // unique constraint on `title`.
  const existingPost = await prismaClient.post.findFirst({
    where: { title: "Wasp Nested Comments" },
  });

  if (!existingPost) {
    await prismaClient.post.create({
      data: {
        title: "Wasp Nested Comments",
        authorId: alice.id,
      },
    });
  }

  // Touch the variables so eslint/static analysis doesn't complain.
  void bob;
};

import React from "react";
import { useParams } from "react-router-dom";
import { useQuery } from "wasp/client/operations";
import { getCommentTree } from "wasp/client/operations";

/**
 * Recursive component that renders a comment and all of its
 * descendants, indented to reflect the depth in the tree.
 */
function CommentNode({ node, depth }) {
  const indent = { marginLeft: `${depth * 20}px` };
  return (
    <div className="comment-node" style={indent}>
      <div className="comment-bubble">
        <span className="comment-author">
          {node.authorUsername ?? "anonymous"}
        </span>
        <span className="comment-content">{node.content}</span>
      </div>
      {node.children && node.children.length > 0 ? (
        <div className="comment-children">
          {node.children.map((child) => (
            <CommentNode key={child.id} node={child} depth={depth + 1} />
          ))}
        </div>
      ) : null}
    </div>
  );
}

export const PostPage = () => {
  const { postId: postIdParam } = useParams();
  const postId = Number.parseInt(postIdParam, 10);

  const { data, error, isLoading } = useQuery(getCommentTree, { postId });

  if (Number.isNaN(postId)) {
    return (
      <div className="container">
        <h1>Invalid post id</h1>
        <p>
          The URL <code>/post/{postIdParam}</code> does not contain a valid
          numeric post id.
        </p>
      </div>
    );
  }

  return (
    <div className="container">
      <header className="post-header">
        <a href="/" className="back-link">
          ← All posts
        </a>
        <h1>Post #{postId}</h1>
      </header>

      {isLoading ? (
        <p>Loading comments…</p>
      ) : error ? (
        <p>Error loading comments: {String(error)}</p>
      ) : data && data.length > 0 ? (
        <div className="comment-tree">
          {data.map((node) => (
            <CommentNode key={node.id} node={node} depth={0} />
          ))}
        </div>
      ) : (
        <p>No comments yet.</p>
      )}
    </div>
  );
};

import React from "react";
import { useQuery, getPosts } from "wasp/client/operations";
import "./Main.css";

export const MainPage = () => {
  const { data: posts, isLoading, error } = useQuery(getPosts);

  return (
    <div className="container">
      <main>
        <h1>Nested Comments Demo</h1>
        <p>
          This is the <code>MainPage</code> at route <code>/</code>. Click a post
          to view its threaded comment tree.
        </p>

        {isLoading ? (
          <p>Loading posts…</p>
        ) : error ? (
          <p>Error loading posts: {String(error)}</p>
        ) : posts && posts.length > 0 ? (
          <ul className="post-list">
            {posts.map((p) => (
              <li key={p.id}>
                <a href={`/post/${p.id}`}>{p.title}</a>
              </li>
            ))}
          </ul>
        ) : (
          <p>
            No posts yet. Run <code>wasp db seed devSeed</code> to create seed
            data.
          </p>
        )}
      </main>
    </div>
  );
};

