  margin: 0.3rem 0;
}

/* Post page */
.post-header {
  width: 100%;
  margin-bottom: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.back-link {
  font-size: 0.95rem;
  color: #555;
  text-decoration: none;
}

.back-link:hover {
  text-decoration: underline;
}

/* Comment tree */
.comment-tree {
  width: 100%;
}

.comment-node {
  margin: 0.4rem 0;
}

.comment-bubble {
  background: #f7f7f9;
  border: 1px solid #e1e1e8;
  border-radius: 6px;
  padding: 0.6rem 0.9rem;
}

.comment-author {
  display: inline-block;
  font-weight: 600;
  margin-right: 0.5rem;
  color: #5b5bd6;
}

.comment-content {
  display: inline;
}

.comment-children {
  margin-top: 0.3rem;
}
